{
  "title": "时间循环之谜",
  "scene": "你站在一个废弃的图书馆中，空气中弥漫着霉味。书架上散落着各种古书和尘封的日记。墙上的钟显示早上8点整。你记得昨晚读到一条线索，说是在图书馆中某本书里藏着解开时间循环的关键。但你不知道是哪一本书，只是隐约记得那本书的封面上有古怪的符号，而且它应该被放在某个不显眼的位置。",
  "goal": "找到那本书，并解开时间循环的谜题。",
  "clue": "关键线索是：古怪符号的书在某个不显眼的位置。",
  "choices": [
    {
      "id": "A",
      "text": "仔细检查每一本书的封面上是否有古怪符号",
      "outcome": "经过几个小时的检查，只发现了一些无意义的符号，没有找到关键线索。",
      "result": "fail",
      "next": "retry"
    },
    {
      "id": "B",
      "text": "查看图书馆中的藏书目录，寻找有古怪符号的书名",
      "outcome": "你找到了一本名为《时间之书》的书，上面有你记得的那个古怪符号。这本书通常在图书馆的最深处，几乎从没有人会找它。",
      "result": "success",
      "next": "next_level"
    },
    {
      "id": "C",
      "text": "直接去询问图书馆管理员，看是否有书藏着古怪符号",
      "outcome": "管理员只是摇头，说从未听说过有这样一本古怪的书。这给你一种不祥的预感，心里更加坚信那本书存在，只是你还没有找到它。",
      "result": "partial",
      "next": "next_level"
    }
  ]
}
